CREATE TABLE workflow_rules(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('event','time','routing')),position INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','paused','cancelled')),draft_json TEXT NOT NULL,published_version INTEGER NOT NULL DEFAULT 0,owner_id TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX workflow_rules_order ON workflow_rules(project_id,kind,state,position,id);
CREATE TABLE workflow_rule_versions(rule_id TEXT NOT NULL REFERENCES workflow_rules(id) ON DELETE CASCADE,project_id TEXT NOT NULL,version INTEGER NOT NULL,definition_json TEXT NOT NULL,published_by TEXT NOT NULL,published_at INTEGER NOT NULL,event_after_id INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(rule_id,version));
CREATE TRIGGER workflow_version_immutable BEFORE UPDATE ON workflow_rule_versions BEGIN SELECT RAISE(ABORT,'Published workflow versions are immutable'); END;
CREATE TABLE workflow_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,rule_id TEXT NOT NULL REFERENCES workflow_rules(id) ON DELETE CASCADE,version INTEGER NOT NULL,event_id TEXT NOT NULL,rule_name TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('running','complete','skipped','failed','pending','uncertain','cancelled','not_delivered')),explanation TEXT NOT NULL,actions_json TEXT NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,frontier_json TEXT NOT NULL,lease_token TEXT,lease_until INTEGER,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER,reason TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(rule_id,version,event_id,conversation_id));
CREATE INDEX workflow_runs_ticket ON workflow_runs(project_id,conversation_id,created_at);
CREATE INDEX workflow_runs_resume ON workflow_runs(state,next_attempt_at) WHERE state IN ('running','pending');
CREATE TABLE workflow_action_receipts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,source TEXT NOT NULL,actor_id TEXT NOT NULL,claim_token TEXT NOT NULL,created_at INTEGER NOT NULL,changes_json TEXT NOT NULL);
CREATE TABLE workflow_notifications(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,kind TEXT NOT NULL,recipient_id TEXT,message TEXT,state TEXT NOT NULL CHECK(state IN ('pending','sending','complete','failed','uncertain','cancelled','not_delivered')),detail TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX workflow_notifications_pending ON workflow_notifications(state,created_at);
CREATE TABLE workflow_time_state(rule_id TEXT NOT NULL REFERENCES workflow_rules(id) ON DELETE CASCADE,project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,version INTEGER NOT NULL,episode TEXT NOT NULL,eligible INTEGER NOT NULL,last_event_id INTEGER NOT NULL DEFAULT 0,last_run_at INTEGER,PRIMARY KEY(rule_id,conversation_id,version));
-- Closed is the terminal lifecycle boundary. New installations and upgrades both
-- get the default; leads can pause it or publish an edited immutable version.
INSERT INTO workflow_rules(id,project_id,name,kind,position,state,draft_json,published_version,owner_id,created_at,updated_at)
 SELECT 'workflow:auto-close:'||id,id,'Close solved tickets after 4 days','time',1000,'published','{"name":"Close solved tickets after 4 days","kind":"time","position":1000,"conditions":{"all":[{"field":"status_category","op":"eq","value":"solved"}],"any":[]},"time":{"field":"solved_at","hours":96},"actions":[{"type":"status","status_id":"closed"}]}',1,'system',CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) FROM projects;
INSERT INTO workflow_rule_versions(rule_id,project_id,version,definition_json,published_by,published_at) SELECT id,project_id,1,draft_json,'system',created_at FROM workflow_rules WHERE id='workflow:auto-close:'||project_id;
CREATE TRIGGER workflow_project_close_default AFTER INSERT ON projects BEGIN
 INSERT INTO workflow_rules(id,project_id,name,kind,position,state,draft_json,published_version,owner_id,created_at,updated_at) VALUES('workflow:auto-close:'||NEW.id,NEW.id,'Close solved tickets after 4 days','time',1000,'published','{"name":"Close solved tickets after 4 days","kind":"time","position":1000,"conditions":{"all":[{"field":"status_category","op":"eq","value":"solved"}],"any":[]},"time":{"field":"solved_at","hours":96},"actions":[{"type":"status","status_id":"closed"}]}',1,'system',CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER));
 INSERT INTO workflow_rule_versions(rule_id,project_id,version,definition_json,published_by,published_at) SELECT id,project_id,1,draft_json,'system',created_at FROM workflow_rules WHERE id='workflow:auto-close:'||NEW.id;
END;

CREATE TABLE workflow_scheduler_cursors(rule_id TEXT PRIMARY KEY REFERENCES workflow_rules(id) ON DELETE CASCADE,project_id TEXT NOT NULL,version INTEGER NOT NULL,hour INTEGER NOT NULL,after_id TEXT NOT NULL DEFAULT '',complete INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL);
CREATE TRIGGER workflow_run_audit_insert AFTER INSERT ON workflow_runs BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json) VALUES(lower(hex(randomblob(16))),NEW.project_id,NEW.created_at,'data','workflow.rule.planned','succeeded','system',NEW.rule_id,'system','conversation',NEW.conversation_id,json_object('run_id',NEW.id,'version',NEW.version));
END;
CREATE TRIGGER workflow_run_audit_state AFTER UPDATE OF state ON workflow_runs WHEN OLD.state<>NEW.state BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json) VALUES(lower(hex(randomblob(16))),NEW.project_id,NEW.updated_at,'data','workflow.rule.'||NEW.state,CASE WHEN NEW.state IN ('failed','uncertain') THEN 'failed' ELSE 'succeeded' END,'system',NEW.rule_id,'system','conversation',NEW.conversation_id,json_object('run_id',NEW.id,'version',NEW.version));
END;
CREATE TRIGGER workflow_notice_audit AFTER INSERT ON workflow_notifications BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json) VALUES(lower(hex(randomblob(16))),NEW.project_id,NEW.created_at,'integration','workflow.notice.queued','succeeded','system','workflows','system','conversation',NEW.conversation_id,json_object('notice_id',NEW.id,'kind',NEW.kind));
END;
CREATE TRIGGER workflow_notice_state_audit AFTER UPDATE OF state ON workflow_notifications WHEN OLD.state<>NEW.state BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json) VALUES(lower(hex(randomblob(16))),NEW.project_id,NEW.updated_at,'integration','workflow.notice.'||NEW.state,CASE WHEN NEW.state IN ('failed','uncertain') THEN 'failed' ELSE 'succeeded' END,'system','workflows','system','conversation',NEW.conversation_id,json_object('notice_id',NEW.id,'kind',NEW.kind));
END;
